        with self._lock:
            # Append-only: no updates or deletes allowed
            self._journal.append(transaction)

    def get_by_idempotency_key(self, key: str) -> Optional[Transaction]:
        with self._lock:
            for tx in self._journal:
                if tx.idempotency_key == key:
                    return tx
